/* CanLin built-in font data (src/render internal, canlin#22, UI spec §6.3).
 *
 * font_builtin.c is generated by tools/mkfont.py: an Inter Latin subset and the
 * glyph ranges baked from it. Trusted, shipped data; theme TTF blobs never go here.
 */
#ifndef CANLIN_FONT_BUILTIN_H
#define CANLIN_FONT_BUILTIN_H

#include "canlin/nk.h"

/* Codepoint drawn for any character the built-in font lacks: U+25A1 WHITE SQUARE. */
#define CANLIN_FONT_BUILTIN_BOX 0x25A1u

extern const unsigned char canlin_font_builtin_ttf[];
extern const unsigned long canlin_font_builtin_ttf_size;
/* Nuklear range list: inclusive (first, last) pairs, 0-terminated, sorted. */
extern const nk_rune canlin_font_builtin_ranges[];

#endif
